          onPress={() => go("/alunos/link")}
          style={styles.summaryItem}
        >
          <Text style={[styles.value, { color: t.accent }]}>
            {requests.data && !requests.error ? pending.length : "—"}
          </Text>
          <Label size={11}>Cadastros pendentes</Label>
        </Pressable>
        <View style={[styles.divider, { backgroundColor: t.border }]} />
        <View style={styles.summaryItem}>
          <Text style={[styles.value, { color: t.text }]}>
            {count(due.length)}
          </Text>
          <Label size={11}>Avaliações a fazer</Label>
        </View>
        <View style={[styles.divider, { backgroundColor: t.border }]} />
        <View style={styles.summaryItem}>
          <Text style={[styles.value, { color: t.text }]}>
            {count(active.reduce((sum, x) => sum + x.weeklyFrequency, 0))}
          </Text>
          <Label size={11}>Sessões / semana</Label>
        </View>
      </View>
      <View
        style={{
          flexDirection: width >= 900 ? "row" : "column",
          gap: 20,
          alignItems: "stretch",
        }}
      >
        <View style={{ flex: 1, minWidth: 0 }}>
          <Card>
            <Label size={18} bold>
              Seus alunos
            </Label>
            <View style={styles.grid}>
              <Shortcut
                title="Adicionar aluno"
                icon="+"
                primary
                onPress={() => setCreate(true)}
              />
              <Shortcut
                title="Link de cadastro"
                icon="↗"
                primary
                onPress={() => go("/alunos/link")}
              />
            </View>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Ver meus alunos"
              onPress={() => go("/alunos")}
              style={[
                styles.studentRow,
                { backgroundColor: t.backgroundElement },
              ]}
            >
              <View style={{ flex: 1, gap: 8 }}>
                <Label size={16} bold>
                  Meus alunos
                </Label>
                <View
                  style={{ flexDirection: "row", flexWrap: "wrap", gap: 10 }}
                >
                  <Label size={12}>Ativos: {count(active.length)}</Label>
                  <Label size={12}>Pausados: {count(paused.length)}</Label>
                  <Label size={12}>Inativos: {count(inactive.length)}</Label>
                </View>
              </View>
              <Label size={24}>›</Label>
            </Pressable>
            {ready && !students.data?.length && (
              <Notice>
                Adicione seu primeiro aluno ou compartilhe seu link de cadastro.
              </Notice>
            )}
          </Card>
          <Card>
            <Label size={18} bold>
              Treinos
            </Label>
            <View style={styles.grid}>
              <Shortcut
                title="Prescrever treino"
                caption="Selecione um aluno"
                icon="≡"
                onPress={() => go("/alunos")}
              />
              <Shortcut
                title="Biblioteca de exercícios"
                caption="Exercícios e vídeos"
                icon="▷"
                onPress={() => go("/exercicios")}
              />
              <Shortcut
                title="Programas"
                caption="Organize suas rotinas"
                icon="▦"
                onPress={() => go("/programas")}
              />
              <Shortcut
                title="Modelos de avaliação"
                caption="Questionários e versões"
                icon="✓"
                onPress={() => go("/modelos")}
              />
            </View>
          </Card>
        </View>
        <View style={{ flex: 1, minWidth: 0 }}>
          <Card>
            <Label size={18} bold>
              Próximos cuidados
            </Label>
            <Label muted>Avaliações previstas para hoje ou em atraso.</Label>
            {ready && !due.length && (
              <Notice>Nenhuma avaliação pendente.</Notice>
            )}
            {due.map((student) => (
              <View key={student.id} style={styles.listItem}>
                <Label bold>{student.name}</Label>
                <Label size={12} muted>
                  {formatDate(student.nextEvaluationDate)}
                </Label>
                <Button
                  variant="secondary"
                  onPress={() => go(`/alunos/${student.id}`)}
                >
                  Ver prontuário
                </Button>
              </View>
            ))}
          </Card>
          {!!students.data?.length && (
            <Card>
              <Label size={18} bold>
                Acompanhamento
              </Label>
              {students.data.slice(0, 5).map((student) => (
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={`Abrir acompanhamento de ${student.name}`}
                  key={student.id}
                  onPress={() => go(`/alunos/${student.id}`)}
                  style={[
                    styles.studentRow,
                    { borderBottomWidth: 1, borderColor: t.border },
                  ]}
                >
                  <View style={{ flex: 1 }}>
                    <Label bold>{student.name}</Label>
                    <Label muted size={12}>
                      {student.mainGoal}
                    </Label>
                  </View>
                  <Label size={22}>›</Label>
                </Pressable>
              ))}
            </Card>
          )}
        </View>
      </View>
      {create && (
        <Dialog title="Cadastrar aluno" onClose={() => setCreate(false)}>
          {programs.error ? (
            <>
              <Notice error>{programs.error}</Notice>
              <Button onPress={() => void programs.reload()}>
                Tentar novamente
              </Button>
            </>
          ) : !programs.data ? (
            <Notice>Carregando formulário…</Notice>
          ) : (
            <StudentForm
              programs={programs.data}
              onSaved={(student) => {
                setCreate(false);
                go(`/alunos/${student.id}`);
              }}
            />
          )}
        </Dialog>
      )}
    </Page>
  );
}

