          description="As prescrições existentes serão preservadas."
          onClose={() => setArchive(null)}
          onConfirm={async () => {
            await api(`/exercises/${archive.id}`, "PUT", {
              ...archive,
              status: archive.status === "ativo" ? "arquivado" : "ativo",
