export function PlanForm({
  studentId,
  plan,
  done,
  cancel,
  initialWorkout = null,
  initialPicker = false,
}: {
  initialWorkout?: number | null;
  initialPicker?: boolean;
  studentId: string;
  plan?: Plan;
  done: () => void;
  cancel: () => void;
}) {
  const [data, setData] = useState<PlanData>(
    plan ?? {
      title: "",
      objective: "Adaptação",
      difficulty: "Iniciante",
      startsAt: today(),
      endsAt: null,
      instructions: "",
      status: "rascunho",
      workouts: [],
    },
  );
  const [open, setOpen] = useState<number | null>(initialWorkout);
  const [remove, setRemove] = useState<number | null>(null);
  const [pending, setPending] = useState(initialPicker);
  const [pickerWorkout, setPickerWorkout] = useState(initialPicker ? initialWorkout : null);
  return (
    <SaveForm
      label="Salvar plano"
      cancel={cancel}
      save={async () => {
        if (pending)
          throw new Error(
            "Confirme ou cancele a prescrição aberta antes de salvar.",
          );
        const parsed = planSchema.safeParse(data);
        if (!parsed.success)
          throw new Error(
            parsed.error.issues
              .map((i) => `${i.path.join(".")}: ${i.message}`)
              .join(" · "),
          );
        await api(
          plan
            ? `/workout-plans/${plan.id}`
            : `/students/${studentId}/workout-plans`,
          plan ? "PUT" : "POST",
          parsed.data,
        );
        done();
      }}
    >
      <TextFields
        value={data}
        change={setData}
        fields={[
          ["title", "Nome do plano *"],
          ["objective", "Objetivo *"],
