          ["endsAt", "Data de término (AAAA-MM-DD)"],
          ["instructions", "Orientações gerais"],
        ]}
      />
      <Choices
        label="Dificuldade"
        value={data.difficulty}
        onChange={(v) =>
          setData({ ...data, difficulty: v as PlanData["difficulty"] })
