                setOpen(data.workouts.length);
              }}
            >
              Duplicar treino
            </Button>
            <Button
              label={`Subir treino ${index + 1}`}
              disabled={pending || index === 0}
              variant="secondary"
              onPress={() => {
                setData({ ...data, workouts: move(data.workouts, index, -1) });
                setOpen(null);
              }}
            >
              ↑
            </Button>
            <Button
              label={`Descer treino ${index + 1}`}
              disabled={pending || index === data.workouts.length - 1}
              variant="secondary"
              onPress={() => {
                setData({ ...data, workouts: move(data.workouts, index, 1) });
                setOpen(null);
              }}
            >
              ↓
            </Button>
            <Button
              disabled={pending}
              variant="danger"
              onPress={() => setRemove(index)}
            >
              Excluir treino
            </Button>
          </View>
          {open === index && (
            <WorkoutEditor
              workout={w}
              initialPicker={index === pickerWorkout}
              pending={(value) => { setPending(value); setPickerWorkout(null); }}
              change={(next) =>
                setData({
                  ...data,
                  workouts: data.workouts.map((x, i) =>
                    i === index ? next : x,
                  ),
                })
              }
            />
          )}
        </Card>
      ))}
      <Button
        disabled={pending}
        variant="secondary"
        onPress={() => {
          setData({
            ...data,
            workouts: [
              ...data.workouts,
              {
                name: `Treino ${String.fromCharCode(65 + data.workouts.length)}`,
