        label="Repetições (ex.: 10 ou 8-12)"
        value={data.repetitions}
        onChangeText={(v) => setData({ ...data, repetitions: v })}
      />}
      <Field
        label="Cadência"
        value={data.cadence}
        onChangeText={(v) => setData({ ...data, cadence: v })}
      />
      <Field
        label="Observações da prescrição"
        multiline
        value={data.notes}
        onChangeText={(v) => setData({ ...data, notes: v })}
      />
    </SaveForm>
  );
}

