export function move<T>(items: T[], index: number, step: number) {
  const next = [...items];
  if (index + step < 0 || index + step >= next.length) return next;
  [next[index], next[index + step]] = [next[index + step], next[index]];
  return next;
}

export function move<T>(items: T[], index: number, step: number) {
  const next = [...items];
  if (index + step < 0 || index + step >= next.length) return next;
  [next[index], next[index + step]] = [next[index + step], next[index]];
  return next;
}

